#include <bits/stdc++.h>using namespace std;using ll = long long;ll value(vector<int>& a) {    ll ans = 0;    int curMax = 0;    for (int x : a) {        curMax = max(curMax, x);        ans += curMax;    }    return ans;} int main() {	// your code goes here    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;    while (t--) {        int n;        cin >> n;        vector<int> a(n);        for (int i = 0; i < n; i++) {            cin >> a[i];        }         long long best = value(a);                 for (int i = 0; i < n; i++) {            for (int j = i + 1; j < n; j++) {                swap(a[i], a[j]);                best = max(best, value(a));                swap(a[i], a[j]); // restore            }        }         cout << best << '\n';    }    return 0; }